<?php if(!isset($db) || !admin()){http_response_code(403);exit;}
$kind=$_GET['kind']??'';$where='';$args=[];
if(isset($eventTypes[$kind])) {$where=' WHERE p.event_type=?';$args[]=$kind;}
$total=(int)rows('SELECT COUNT(*) n FROM projects p'.$where,$args)[0]['n'];$pages=max(1,(int)ceil($total/50));$pageNo=max(1,min($pages,(int)($_GET['p']??1)));$offset=($pageNo-1)*50;
$works=rows('SELECT p.*, (SELECT COUNT(*) FROM recipients r WHERE r.project_id=p.id AND r.certificate_number IS NOT NULL) numbered,(SELECT COUNT(*) FROM recipients r WHERE r.project_id=p.id AND r.certificate_number IS NOT NULL AND r.issued=0) revoked FROM projects p'.$where.' ORDER BY p.date DESC,p.id DESC LIMIT 50 OFFSET '.$offset,$args);
?>
<div class="page-heading"><div><p class="eyebrow">MANAGEMENT REPORTS</p><h1>รายงานสำหรับผู้บริหาร</h1><p class="muted">ภาพรวมงานและทะเบียนเกียรติบัตรของวิทยาลัย · ดูข้อมูลและพิมพ์รายงาน</p></div><button class="guide-print" onclick="window.print()">พิมพ์ / PDF</button></div><article class="card user-guide"><div class="stats"><div class="stat"><span>งานทั้งหมดในระบบ</span><strong><?=rows('SELECT COUNT(*) n FROM projects')[0]['n']?></strong></div><div class="stat"><span>เลขที่ที่ลงทะเบียนทั้งหมด</span><strong><?=rows('SELECT COUNT(*) n FROM recipients WHERE certificate_number IS NOT NULL')[0]['n']?></strong></div><div class="stat"><span>รายการเพิกถอน</span><strong><?=rows('SELECT COUNT(*) n FROM recipients WHERE certificate_number IS NOT NULL AND issued=0')[0]['n']?></strong></div></div><form method="get" class="search-form guide-print"><input type="hidden" name="page" value="reports"><select name="kind" aria-label="ประเภทงาน"><option value="">ทุกประเภทงาน</option><?php foreach($eventTypes as $key=>$label):?><option value="<?=$key?>" <?=$kind===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select><button>แสดงรายงาน</button></form><p>ประเภท: <?=e($eventTypes[$kind]??'ทุกประเภทงาน')?> · <?=$total?> งาน · หน้า <?=$pageNo?> / <?=$pages?> (พิมพ์เฉพาะรายการในหน้านี้)</p><div class="table-wrap"><table><thead><tr><th>งาน / ผู้รับผิดชอบ</th><th>ประเภท / วันที่</th><th>ออกเลขแล้ว</th><th>เพิกถอน</th><th>รายงาน</th></tr></thead><tbody><?php foreach($works as $work):?><tr><td><?=e($work['title'])?><small><?=e($work['owner'])?></small></td><td><?=e($eventTypes[$work['event_type']]??'งานอื่น ๆ')?><small><?=projectDates($work)?></small></td><td><?=$work['numbered']?></td><td><?=$work['revoked']?></td><td><a class="text-link" href="?page=report&id=<?=$work['id']?>">ดูรายงาน / ภาพกิจกรรม →</a></td></tr><?php endforeach ?><?php if(!$works):?><tr><td colspan="5">ยังไม่มีข้อมูล</td></tr><?php endif ?></tbody></table></div><p class="guide-print"><?php if($pageNo>1):?><a class="button secondary" href="?page=reports&kind=<?=e($kind)?>&p=<?=$pageNo-1?>">← ก่อนหน้า</a><?php endif ?> <?php if($pageNo<$pages):?><a class="button secondary" href="?page=reports&kind=<?=e($kind)?>&p=<?=$pageNo+1?>">ถัดไป →</a><?php endif ?></p></article>
